/*
Cell types are
    0: x, red
    1: y, green
    2: z, blue
    3: open, white
    4: closed, gray

Compared to the original implementation,
    it is more straightforward to define when to remove a wall, than to define when to keep a wall.
        e.g. placing doors in corridor direction (a != v && b != v).
    has open cells that remove walls when both cells are open.
    has closed cells that only connect to other closed cells.
    z cells act like open cells with different background.

Toggle F: display cell type
*/

// Picks a random cell type. The exact distribution depends on position to achieve a given look.
int tile(vec2 x)
{
    vec4 w = texelFetch(iChannel0, ivec2(round(x.x/30.) + 5., 0) % 1024, 0);
    vec2 y = vec2(x.x - round(x.x/30.)*30. - (w.x - .5) * 15., x.y);
    if (length(y) > 3.)
    {
        if (length(y) < 6.) return 3;
        if (length(y.y) < 2.) return 3;
        if (length(y.x) < 2. && y.y < 0. && w.y < .3) return 3;
        if (length(y.x) < 2. && y.y > 0. && w.z < .3) return 3;
    }
    //else if (length(y) > 1.5) return 4;
    vec4 v = texelFetch(iChannel0, ivec2(x) % 1024, 0);
    if (v.r < .25) return 0;
    if (v.r < .5 ) return 1;
    return 2;
}

// Decides if a wall
//    should be placed between
//        cell        with type (a) and
//        cell+dir(v) with type (b).
bool wall(int v, int a, int b)
{
    if (a == 4 || b == 4) return a != b;
    return a != v && b != v && (a != 2 || b != 2) && (a != 3 || b != 3);
}

vec2 uv;
float line(vec2 a, vec2 b)
{
    vec2 q = uv - a;
    b -= a;
    return length(q - b * clamp(dot(q, b) / dot(b, b), 0., 1.));
}

mat2 R(float a) { return mat2(cos(a), sin(a), -sin(a), cos(a)); }

void mainImage(out vec4 C, vec2 fragCoord)
{
    float f = min(23., iResolution.y / 20.);
    uv = floor(fragCoord - iResolution.xy / 2.) / f;
    if (iMouse.z > 0.) uv -= (iMouse.xy - iResolution.xy / 2.) / f;
    uv.y += tanh(2. * sin(iTime / 2.)) * 1.;
    uv *= R(tanh(2. * cos(iTime / 2.)) / 8.);
    uv.x += iTime * 2.;
    C = vec4(1);

    vec2 cell = round(uv);
    int c = tile(cell);
    if (texelFetch(iChannel3, ivec2(0x46, 2), 0).x < .5) // Toggle F
    {
        if (c != 3)
            C = mix(C, vec4(0,0,0,1), .1);
        if (c == 0)
            C = mix(C, vec4(1,0,0,1), clamp(1. - length(uv.y - cell.y) * f, 0., 1.));
        if (c == 1)
            C = mix(C, vec4(0,1,0,1), clamp(1. - length(uv.x - cell.x) * f, 0., 1.));
        if (c == 2)
            C = mix(C, vec4(0,0,1,1), clamp(1.5 - length(uv - cell) * f, 0., 1.));
    }

    float r = 1e9;
    for (int i=-1 ; i<=1 ; i++)
    for (int j=-1 ; j<=0 ; j++)
    {
        if (wall(1, tile(cell + vec2(i, j)), tile(cell + vec2(i, j+1))))
            r = min(r, line(cell + .5 + vec2(i-1, j), cell + .5 + vec2(i, j)));
        if (wall(0, tile(cell + vec2(j, i)), tile(cell + vec2(j+1, i))))
            r = min(r, line(cell + .5 + vec2(j, i-1), cell + .5 + vec2(j, i)));
    }
    C = mix(C, vec4(0,0,0,1), clamp(2. - r * f, 0., 1.));

    C = mix(C, vec4(.9), smoothstep(.99, 1.,      fragCoord.x / iResolution.x));
    C = mix(C, vec4(.9), smoothstep(.99, 1., 1. - fragCoord.x / iResolution.x));
    C = mix(C, vec4(.9), smoothstep(.98, 1.,      fragCoord.y / iResolution.y));
    C = mix(C, vec4(.9), smoothstep(.98, 1., 1. - fragCoord.y / iResolution.y));
    C = sqrt(C);
}
